// Compact price-reliability badges for list surfaces. Shows the short
// label with the full explanation as a native tooltip; tapping through
// to the item detail gives the full note block.
const TONES = {
  amber: "border-amber-500/30 bg-amber-500/10 text-amber-300",
  red: "border-red-500/30 bg-red-500/10 text-red-300",
};

export default function PriceNoticeBadge({ notices }) {
  if (!notices || notices.length === 0) return null;
  return (
    <span className="inline-flex flex-wrap items-center gap-1">
      {notices.map((n) => (
        <span
          key={n.id}
          title={n.full}
          className={`inline-flex items-center rounded-sm border px-1.5 py-px font-mono text-[9px] uppercase tracking-wider ${TONES[n.tone] || TONES.amber}`}
        >
          {n.short}
        </span>
      ))}
    </span>
  );
}
